 function publicOutput(route){if(route==='technical-exams')return directoryOutput();if(route==='recruiters')return organizationOutput();if(route==='recruitment-detail')return noticeDetailOutput();return noticesOutput();}
 function publicView(route){sync();readParams();const detail=route==='recruitment-detail'||route==='technical-exams'&&bridge.params().has('examId'),body=detail?'<div class="recruitment-detail-back">'+link(route==='recruitment-detail'?'recruitment':'technical-exams',icon('arrow-left')+' Back to '+(route==='recruitment-detail'?'notice explorer':'technical examinations'))+'</div><div class="recruitment-results" id="recruitmentResults">'+publicOutput(route)+'</div>':publicSummary()+'<div class="recruitment-layout">'+filters()+'<div class="recruitment-results" id="recruitmentResults">'+publicOutput(route)+'</div></div>';return '<div class="recruitment-workspace">'+navigation()+statusMessages()+body+'<p class="recruitment-source-disclosure">'+(state.catalogStatus==='ready'?'Server catalogue response received.':'Using the bundled technical-directory snapshot; live notice monitoring is not implied.')+' Source review status and published eligibility are separate checks.</p></div>';}
