 function preferenceSelect(name,label,options,value){return '<label class="recruitment-field"><span>'+E(label)+'</span><select name="'+name+'" data-recruitment-pref="'+name+'">'+options.map(([id,text])=>'<option value="'+E(id)+'" '+(String(value)===String(id)?'selected':'')+'>'+E(text)+'</option>').join('')+'</select></label>';}
